<script module lang="ts">
/**
 * A histogram showing the distribution of one sample (`design/components/histogram.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/histogram.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  DEFAULT_CHART_MESSAGES,
  UNMEASURED,
  agentMember,
  chartMarks,
  chartPosition,
  chooseChartMark,
  createReading,
  createWarningLog,
  devWarning,
  histogramModel,
  histogramReadout,
  histogramSelection,
  joinSlot,
  measureBox,
  nearestIndex,
  readChartPosition,
  readingRest,
  readingView,
  watchEffect,
  type ChartMessages,
  type ChartTooltipConfig,
  type ChartYAxis,
  type HistogramXAxis,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/charts/histogram.module.css'
import a11y from '@polymorph/recipes/conventions/a11y.module.css'
import chartAxis from '@polymorph/recipes/charts/frame/chart-axis.module.css'
import chartFrame from '@polymorph/recipes/charts/frame/chart-frame.module.css'
import chartTooltip from '@polymorph/recipes/charts/frame/chart-tooltip.module.css'
import chartTwin from '@polymorph/recipes/charts/frame/chart-twin.module.css'
import Button from '../controls/Button.svelte'
import Table from '../structure/Table.svelte'
import TableBody from '../structure/TableBody.svelte'
import TableCell from '../structure/TableCell.svelte'
import TableHead from '../structure/TableHead.svelte'
import TableHeader from '../structure/TableHeader.svelte'
import TableRow from '../structure/TableRow.svelte'

export interface HistogramProps {
  /**
   * A **target** bin count. Defaults to d3's Sturges rule (⌈log₂ n⌉ + 1). `d3-array.bin` may
   * adjust it to clean thresholds, as tick counts are.
   */
  bins?: number
  /**
   * The raw observations, unbinned and in any order; `[]` renders the empty state.
   */
  data: readonly number[]
  /**
   * The accessible name.
   */
  label: string
  /**
   * Shows the previous frame at reduced opacity during a refetch.
   */
  loading?: boolean
  /**
   * The locale for `Intl` formatting.
   */
  locale?: string
  /**
   * The chart tier's string catalog (`ChartMessages`). Defaults to generic English; a localized
   * host passes the same object to every chart.
   */
  messages?: ChartMessages
  /**
   * Called with the read bin's edges and count, on Enter, Space or click.
   */
  onSelect?: (selection: { bin: { from: number; to: number; count: number } }) => void
  size?: 'sm' | 'md' | 'lg'
  /**
   * The per-bin readout: the range and its count. `false` removes the visual layer only.
   */
  tooltip?: false | ChartTooltipConfig
  /**
   * The measure's axis. It is not a `ChartXAxis`: there is no `key`, because the sample is the
   * column, and no `scale`, because it is always linear. Ticks sit at bin edges, thinned to
   * clean steps.
   */
  x?: HistogramXAxis
  /**
   * The count axis, **always zero-anchored** because a truncated bar misstates a count. `domain:
   * 'auto'` raises a dev warning and is ignored, as in BarChart.
   */
  y?: ChartYAxis
}
</script>

<script lang="ts">
let {
  bins,
  data,
  label: labelOwn,
  loading = false,
  locale,
  messages = (() => DEFAULT_CHART_MESSAGES)(),
  onSelect,
  size = 'md',
  tooltip = (() => ({}))(),
  x,
  y,
}: HistogramProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn, size: size }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const listening = {
  get select() {
    return onSelect !== undefined
  },
}
let box = $state(UNMEASURED)
let reading = $state(createReading({ count: 0, seriesStart: null }))
let position = $state(readingRest(null))
let twinOpen = $state(false)
let warningLog = $state(createWarningLog())
let frame = $state<HTMLElement | null>(null)
let plot = $state<HTMLElement | null>(null)
const input = $derived({
  data,
  bins,
  x,
  y,
  label,
  locale,
  messages,
  tooltip,
  loading,
  selectable: listening.select,
  box,
})
const model = $derived(histogramModel(input))
const view = $derived(readingView(position, model.bins.length))
const readout = $derived(histogramReadout(input, model, view))
const activate = $derived(() => {
  const selection = histogramSelection(input, model, reading.now())
  if (selection !== null) onSelect?.(selection)
})
const walk = $derived({ count: model.bins.length })
const marks = $derived({
  walk,
  input,
  model,
  readout: histogramReadout,
  selection: histogramSelection,
})
const onKey = $derived((event: KeyboardEvent) => {
  if (listening.select && (event.key === 'Enter' || event.key === ' ')) {
    event.preventDefault()
    activate()
    return
  }
  reading.update(walk)
  if (reading.key(event.key)) event.preventDefault()
})
const onPointer = $derived((event: PointerEvent) => {
  if (model.plot === null) return
  const rect = (event.currentTarget as Element).getBoundingClientRect()
  reading.moveTo(nearestIndex(model.positions, event.clientX - rect.left))
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    box = plot === null ? box : measureBox(plot, box)
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [plot]) if (element) resize?.observe(element)
  release1 = () => {
    resize?.disconnect()
  }
  run()
}
watchEffect(effect1)
onDestroy(() => release1?.())
const effect2 = () => {
  reading.subscribe((now) => {
    position = now
  })
}
watchEffect(effect2)
const effect3 = () => {
  warningLog.log(model.warnings, (message) => devWarning(true, message))
}
watchEffect(effect3, { watch: () => model.warnings.join('\n') })
let release4: (() => void) | undefined
const effect4 = () => {
  release4?.()
  const ran = !listening.select
    ? () => {}
    : agentMember({
        member: 'Histogram',
        element: () => frame,
        state: () => ({
          items: chartMarks(marks, reading),
          position: chartPosition(marks, reading),
          count: walk.count,
        }),
        actions: {
          read: { argument: 'number', run: (value) => readChartPosition(marks, value, reading) },
          choose: {
            argument: 'id',
            run: (value) => chooseChartMark(marks, value, reading, activate),
          },
        },
      })
  release4 = () => {
    ran()
  }
}
watchEffect(effect4)
onDestroy(() => release4?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<figure
    bind:this={frame}
    class={chartFrame.frame}
    data-size={size}
    data-state={model.state}
    data-position={view.active ? view.index : undefined}
    aria-label={label}
    data-member="histogram"
    ><div class={chartFrame.region}
      ><div class={chartFrame.yAxis}
        >{#if (model.axes?.y) !== undefined
          }<div class={chartAxis.axis} data-orientation="y" aria-hidden="true"
            >{#each (model.axes?.y) ?? [] as tick (tick.key)
              }<span class={chartAxis.tick} style:top={`${tick.at}px`} data-align={tick.align}
                >{tick.label
              }</span
            >{/each
          }</div
        >{/if
      }</div
      ><div bind:this={plot} class={chartFrame.plot}
        >{#if model.state === 'empty'
          }<div class={chartFrame.empty}><span>{messages.empty}</span></div
        >{:else
          }<div
            class={styles.surface}
            tabindex="0"
            role="img"
            aria-label={label}
            onkeydown={(event) => { onKey(event) }}
            onclick={() => { activate() }}
            onpointermove={(event) => { onPointer(event) }}
            onpointerleave={() => { reading.clear() }}
            onblur={() => { reading.clear() }}
            >{#if model.plot !== null
              }<svg
                class={styles.marks}
                style:--pm-chart-zero={`${model.plot?.zero}px`}
                data-reading={(view.active) ? '' : undefined}
                width={model.plot?.width}
                height={model.plot?.height}
                aria-hidden="true"
                focusable="false"
                ><g class={styles.grid}
                  >{#each model.plot?.grid ?? [] as line (line.key)}<path d={line.d}></path>{/each
                }</g
                ><g class={styles.bins}
                  >{#each model.plot?.bars ?? [] as bar (bar.key)
                    }<g data-active={(view.index === bar.index) ? '' : undefined}
                      ><rect
                        class={styles.hit}
                        x={bar.hit.x}
                        y={bar.hit.y}
                        width={bar.hit.width}
                        height={bar.hit.height}
                        onpointerenter={() => { reading.moveTo(bar.index) }}
                      ></rect
                      >{#if bar.d !== null
                        }<path class={styles.bar} d={bar.d ?? undefined}></path
                      >{/if
                    }</g
                  >{/each
                }</g
                ><path class={styles.zero} d={model.plot?.zeroRule}></path
              ></svg
            >{/if
          }</div
        >{/if
        }{#if readout.tooltip !== null
          }<div
            class={chartTooltip.tooltip}
            style:--pm-chart-tip-x={`${readout.tooltip?.x}px`}
            style:--pm-chart-tip-y={`${readout.tooltip?.y}px`}
            data-indicator={readout.tooltip?.indicator}
            data-side={readout.tooltip?.side}
            aria-hidden="true"
            >{#if readout.tooltip?.header !== undefined
              }<p class={chartTooltip.header}>{readout.tooltip?.header}</p
            >{/if
            }<ul class={chartTooltip.rows}
              >{#each readout.tooltip?.rows ?? [] as row (row.key)
                }<li class={chartTooltip.row}
                  ><span class={chartTooltip.key} style:--pm-chart-key={row.paint}></span
                  ><span class={chartTooltip.value}>{row.value}</span
                  ><span class={chartTooltip.label}>{row.label}</span
                ></li
              >{/each
            }</ul
          ></div
        >{/if
      }</div
      ><div class={chartFrame.xAxis}
        >{#if (model.axes?.x) !== undefined
          }<div class={chartAxis.axis} data-orientation="x" aria-hidden="true"
            >{#each (model.axes?.x) ?? [] as tick (tick.key)
              }<span class={chartAxis.tick} style:left={`${tick.at}px`} data-align={tick.align}
                >{tick.label
              }</span
            >{/each
          }</div
        >{/if
      }</div
    ></div
    ><span class={a11y.visuallyHidden}>{model.summary}</span
    ><div class={chartTwin.twin} data-state={twinOpen ? 'open' : 'closed'}
      ><div class={chartTwin.toggle}
        ><Button
          variant="ghost"
          tone="neutral"
          size="sm"
          icon="table"
          iconOnly={true}
          label={twinOpen ? messages.hideTable(label) : messages.showTable(label)}
          onClick={() => { twinOpen = !twinOpen }}
      /></div
      >{#if twinOpen
        }<div class={chartTwin.table}
          ><Table label={messages.tableLabel(label)} caption={messages.tableLabel(label)}
            ><TableHead
              ><TableRow
                >{#each model.twin.columns as column (column.key)
                  }<TableHeader numeric={column.numeric}>{column.label}</TableHeader
                >{/each
              }</TableRow
            ></TableHead
            ><TableBody
              >{#each model.twin.rows as row, line (line)
                }<TableRow
                  >{#each row as cell, cellIndex (model.twin.columns[cellIndex]?.key ?? cellIndex)
                    }<TableCell numeric={model.twin.columns[cellIndex]?.numeric}
                      >{cell === '' ? '—' : cell
                    }</TableCell
                  >{/each
                }</TableRow
              >{/each
            }</TableBody
          ></Table
        ></div
      >{/if
    }</div
    ><span class={a11y.visuallyHidden}
      ><div aria-live="polite" aria-atomic="true">{readout.announcement}</div
    ></span
  ></figure
>{/if
}{@render joined.end?.()}
